// Subscribe once, for example in the form constructor:
openFileDialog1.FileOk += openFileDialog1_FileOk;

private void openFileDialog1_FileOk(object sender, CancelEventArgs e)
{
    // requires: using System.IO;
    if (new FileInfo(openFileDialog1.FileName).Length > 10 * 1024 * 1024)
    {
        MessageBox.Show("Please choose a file smaller than 10 MB.");
        e.Cancel = true;
    }
}

// Subscribe once, for example in the form constructor:
saveFileDialog1.FileOk += saveFileDialog1_FileOk;

private void saveFileDialog1_FileOk(object sender, CancelEventArgs e)
{
    if (!saveFileDialog1.FileName.EndsWith(".txt", StringComparison.OrdinalIgnoreCase))
    {
        MessageBox.Show("Only .txt files can be saved here.");
        e.Cancel = true;
    }
}

// Subscribe once, for example in the form constructor:
folderBrowserDialog1.HelpRequest += folderBrowserDialog1_HelpRequest;
folderBrowserDialog1.ShowHelp = true; // shows the Help button

private void folderBrowserDialog1_HelpRequest(object sender, EventArgs e)
{
